import csv
import io


def parse_csv(raw_csv: str):
    reader = csv.reader(io.StringIO(raw_csv, newline=""), delimiter=",", quotechar='"')
    records = []

    for record in reader:
        if not records:
            if not record or all(not value.strip() for value in record):
                continue
            if record[0].lstrip("\ufeff \t").startswith("#"):
                continue
            record[0] = record[0].lstrip("\ufeff")
        records.append(record)

    if not records:
        return {"columns": [], "rows": []}

    columns = list(records[0])
    rows = records[1:]

    for row in rows:
        while len(columns) < len(row):
            name = f"column_{len(columns) + 1}"
            while name in columns:
                name += "_"
            columns.append(name)

    width = len(columns)
    normalized_rows = [
        row[:width] + [""] * max(0, width - len(row))
        for row in rows
    ]

    return {"columns": columns, "rows": normalized_rows}
